const $ = (selector) => document.querySelector(selector);
const icons = { chat:'<path d="M20 11a8 8 0 0 1-8 8H4v-8a8 8 0 1 1 16 0Z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',follow:'<path d="m4 7 2 2 4-4M13 7h7M4 15l2 2 4-4M13 15h7"/>',file:'<path d="M6 3h8l4 4v14H6zM13 3v5h5M9 12h6M9 16h6"/>',plus:'<path d="M12 5v14M5 12h14"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="2.5"/><circle cx="16" cy="17" r="2.5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',arrow:'<path d="M12 19V5m-6 6 6-6 6 6"/>',right:'<path d="m9 5 7 7-7 7"/>' };
const icon = (name) => '<svg viewBox="0 0 24 24" aria-hidden="true">'+(icons[name]||icons.file)+'</svg>';
function decorate() { document.querySelectorAll('[data-icon]').forEach((el) => { el.innerHTML=icon(el.dataset.icon); }); }
const escape = (text) => String(text).replace(/[&<>"']/g,(c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const topics=[{id:'offsite',title:'Our November offsite',attention:'Needs you'},{id:'portfolio',title:'Getting the portfolio out',attention:'Draft ready'},{id:'running',title:'Making time to run',attention:''}];
const drafts=new Map(), extras=new Map();
let current='offsite',scenario='returning',queued='',sent=false,drawerTrigger,toastTimer;
let memoryBudget='Keep the offsite under $2,000 in total.', memoryForgotten=false, checkPaused=false;
const user=(text) => '<article class="message user"><div class="message-body">'+escape(text)+'</div></article>';
const agent=(body,source='') => '<article class="message"><div class="byline"><span class="mini-gator">🐊</span>Gator</div><div class="message-body">'+body+'</div>'+(source?'<p class="source">'+source+'</p>':'')+'</article>';
const file=() => '<button class="card file-card" data-drawer="preview"><span class="file-mark">'+icon('file')+'</span><span><strong>Venue comparison</strong><small>Draft · Three options, with costs and trade-offs</small></span>'+icon('right')+'</button>';
const request=() => sent?'<div class="card"><strong>Example email marked as sent</strong><small>Prototype only. No email was sent.</small></div>':'<section class="card"><div class="request-label">Your decision</div><strong>Ask Jamie about the garden room?</strong><p class="request-copy">I’ve drafted an availability request for 12 people, within your $2,000 budget.</p><div class="request-actions"><button class="button" data-review>Review email</button><button class="quiet-button" data-keep>Keep as draft</button></div></section>';
function notify(text) { clearTimeout(toastTimer); $('#toast').textContent=text; $('#toast').hidden=false; toastTimer=setTimeout(()=>$('#toast').hidden=true,4200); }
function renderTopics() { $('#topics').innerHTML=topics.map(t=>'<button class="topic" data-topic="'+t.id+'" data-attention="'+Boolean(t.attention)+'" '+(t.id===current?'aria-current="page"':'')+'><span>'+escape(t.title)+'</span>'+(t.attention?'<small>'+escape(t.attention)+'</small>':'')+'</button>').join(''); }
function render() {
  renderTopics();
  const topic=topics.find(t=>t.id===current);
  $('#topic-title').textContent=current==='main'?'Gator':topic?.title||'New topic';
  $('#topic-subtitle').textContent=scenario==='first'?'Your own personal agent.':'A conversation you can come back to.';
  $('#updates-button').hidden=scenario==='first'; $('#guide').hidden=scenario!=='working';
  $('#message').value=drafts.get(current)||''; $('#draft-status').textContent='';
  $('#local-caption').textContent='Design example · This prototype stores no conversations after you close it.';
  let body='<p class="day">Today</p>';
  if(scenario==='first') body='<section class="first-intro"><div class="hello" aria-hidden="true">🐊</div><h2>Hi. I’m Gator.</h2><p>Bring me a question, a half-formed plan, or something you’d like a hand with.</p><button class="quiet-button" data-drawer="setup">Choose how Gator thinks '+icon('right')+'</button><p class="muted">In the app, model setup is required before Gator can reply. Your first message would be kept while you set up.</p></section>';
  else if(current==='portfolio') body+=user('Can you help me get my portfolio ready for Friday?')+agent('Yes. The project descriptions are the part I’d tackle first. I’ve pulled your rough notes into a draft you can revise.','Example · Based on the files you selected.')+'<button class="card file-card" data-drawer="portfolio"><span class="file-mark">'+icon('file')+'</span><span><strong>Portfolio project descriptions</strong><small>Draft · Three projects</small></span>'+icon('right')+'</button>';
  else if(current==='running') body+=user('I keep planning to run, then work gets in the way.')+agent('Let’s make the plan easier to keep. Which two days usually have a little breathing room?');
  else if(current==='main') body+=agent('What would you like a hand with?')+'<button class="card file-card" data-topic="offsite"><span class="file-mark">'+icon('follow')+'</span><span><strong>Pick up the November offsite</strong><small>One example decision waiting for you</small></span>'+icon('right')+'</button>';
  else if(current==='new') body+=agent('What’s on your mind?');
  else {
    body+=user('Help me keep the November offsite moving. We’ll be 12 people, and I’d like to stay under $2,000.');
    body+=agent('I’ll compare the options you shared and keep the total budget in view. I’ll show you any email before sending it.');
    if(scenario==='asleep') body+='<div class="availability"><strong>The scheduled check didn’t run.</strong><p>This computer was asleep. Last successful check: yesterday at 4:10 PM. I don’t have a fresh availability update.</p><button class="quiet-button" data-check>Review the check</button></div>';
    else if(scenario==='working') body+='<div class="working" role="status"><span></span><span>Comparing the three venue options</span></div>';
    else body+=agent('Quick update: the garden room looks like the best fit. Its quoted cost leaves room in the budget, but availability still needs confirming.'+file()+request(),'Example · Checked the three venue notes at 9:12 AM.');
  }
  $('#messages').innerHTML=body+(extras.get(current)||''); decorate(); $('#transcript').scrollTop=$('#transcript').scrollHeight; renderQueue();
}
function renderQueue() { $('#queue').hidden=!queued; $('#queue p').textContent=queued; $('#composer-note').textContent=scenario==='working'?'Send to queue a separate request, or guide the work already in progress.':''; }
const detail=(title,text,action='',target='') => '<section class="detail-item"><strong>'+title+'</strong><p>'+text+'</p>'+(action?'<button class="quiet-button" data-drawer="'+target+'">'+action+' '+icon('right')+'</button>':'')+'</section>';
function openDrawer(kind,trigger) {
  drawerTrigger=trigger||document.activeElement; const drawer=$('#drawer'); drawer.hidden=false;
  let title='',content='';
  if(kind==='following') { title='Following'; content='<p class="muted">Things you’ve asked Gator to keep track of. These are fictional examples.</p>'+detail('November offsite','Choose a venue for 12 people by Friday. One draft needs your review.','Open the conversation','offsite')+detail('Portfolio launch','Review your project descriptions before Friday. No recurring check configured.','Open the draft','portfolio')+detail('Venue availability check',scenario==='asleep'?'Did not run while the computer was asleep.':'Example: checks the selected venue notes each weekday at 9 AM.','See scope & timing','check'); }
  else if(kind==='updates') { title='Updates for you'; content='<p class="muted">Across your conversations. Opening an update does not approve an action.</p>'+detail('A venue decision is ready','November offsite · Review the draft before anything is sent.','Return to offsite','offsite')+detail('Portfolio draft is ready','Getting the portfolio out · Three project descriptions to review.','Open draft','portfolio'); }
  else if(kind==='saved') { title='Saved'; content='<p class="muted">Files and things Gator remembers, with the conversation they came from.</p>'+detail('Venue comparison','Draft · November offsite','Preview','preview')+detail('Portfolio descriptions','Draft · Portfolio launch','Preview','portfolio')+detail('What Gator remembers','Review the preferences and decisions used in this topic.','Review memories','memories'); }
  else if(kind==='info') { title='About this conversation'; content='<h3>November offsite</h3><p class="muted">Only the example venue notes are selected for this topic.</p>'+detail('Sources','Venue notes · 3 files. Adding a different folder would require your selection.','See example files','attachments')+detail('What Gator remembers','Budget and group size you shared in this conversation.','Review memories','memories')+detail('Connections','No live accounts connected in this prototype.','Manage access','connections')+'<div class="divider"></div><dl><div><dt>Runs on</dt><dd>This computer</dd></div><div><dt>Recurring work</dt><dd>See Following</dd></div></dl><p class="muted" style="margin-top:18px">Ordinary chat does not need a context meter. Technical diagnostics would remain available in settings.</p>'; }
  else if(kind==='preview') { title='Venue comparison'; content='<p class="muted">Example draft · No file has been generated</p><h3 class="preview-title">A little room to get together.</h3><p style="margin-top:17px">The garden room is the strongest option from the notes you shared. Availability and a complete quote still need confirming.</p><table class="preview-table"><thead><tr><th>Venue</th><th>Quoted cost</th></tr></thead><tbody><tr><td>Garden room</td><td>$1,680</td></tr><tr><td>Studio loft</td><td>$1,920</td></tr><tr><td>Riverside table</td><td>$1,440</td></tr></tbody></table><p class="muted">Example figures only. The notes do not establish final fees or live availability.</p><button class="button" data-revise style="margin-top:20px">Ask Gator for a revision</button>'; }
  else if(kind==='portfolio') { title='Portfolio descriptions'; content='<p class="muted">Example draft · No file generated</p><h3 class="preview-title">Work worth sharing.</h3><p style="margin-top:18px">The proposed preview would keep the three project descriptions here, with sources and a way to request revisions in the original topic.</p><button class="quiet-button" data-topic="portfolio">Open portfolio conversation '+icon('right')+'</button>'; }
  else if(kind==='memories') { title='What Gator remembers'; content='<p class="muted">Example preferences, scoped to the offsite topic. Edits affect this prototype only.</p><section class="detail-item memory-item"><label for="memory-budget">Your budget</label><textarea id="memory-budget" rows="2">'+escape(memoryBudget)+'</textarea><p>Source: your message in this topic.</p><button class="quiet-button" data-save-memory>Save correction</button><button class="quiet-button" data-forget>Forget this preference</button></section>'+detail('Group size','12 people. Source: your message in this topic.')+'<p class="muted" style="margin-top:18px">Forgetting a saved preference would not erase messages, files or data in other services.</p>'; }
  else if(kind==='check') { title='Scope & timing'; content='<p class="muted">Example only · No check is running</p><dl><div><dt>Watch</dt><dd>Three selected venue notes</dd></div><div><dt>When</dt><dd>Weekdays, 9 AM SGT</dd></div><div><dt>Until</dt><dd>30 October</dd></div><div><dt>Tell me about</dt><dd>Price or availability changes</dd></div></dl><p style="margin-top:20px">Checks need this computer to be awake, online, and running Gator’s background service.</p><button class="quiet-button" data-pause>Simulate pausing this check</button>'; }
  else if(kind==='search') { title='Find a conversation'; content='<label class="sr-only" for="topic-search">Search conversations</label><input id="topic-search" type="search" placeholder="Search your conversations…"><div id="search-results"></div>'; }
  else if(kind==='settings') { title='Settings'; content=detail('Model & connection','Choose a provider or a local model. Your preferences stay available here.','Model setup','setup')+detail('Connected apps','Review which accounts Gator may use.','Manage connections','connections')+detail('Memories & privacy','Review saved preferences, local history and retention.','Review this topic’s memories','memories')+detail('About & updates','Version and update controls belong here, away from the conversation.'); }
  else if(kind==='setup') { title='Choose a model'; content='<p>Production would open Gator’s existing model setup here, preserving your message.</p><p class="muted">This prototype has no model or API connection. Your request will not be sent anywhere.</p><button class="button" data-close>Back to my message</button>'; }
  else if(kind==='connections') { title='Connected apps'; content='<p>No live accounts are connected.</p><p class="muted">When a request needs an account, Gator should explain the specific access needed and open the real sign-in flow. This example requests no permissions.</p>'; }
  else if(kind==='attachments') { title='Share something with Gator'; content='<p>A file, screenshot or link should join the conversation where it is useful.</p><p class="muted">Production needs host-owned file selection, supported-format feedback and scoped access. This prototype does not read your files.</p>'+detail('Venue notes','Three fictional source files used to illustrate this conversation.'); }
  else if(kind==='offsite') { closeDrawer(); switchTopic('offsite'); return; }
  if(kind==='memories'&&memoryForgotten) content='<p class="muted">The example budget preference was forgotten. Messages are unchanged.</p>';
  if(kind==='check'&&checkPaused) content='<p>The example check is paused.</p><p class="muted">No real check is running.</p>';
  $('#drawer-title').textContent=title; $('#drawer-content').innerHTML=content; decorate();
  if(kind==='search') { const input=$('#topic-search'); const update=()=>{ $('#search-results').innerHTML=topics.filter(t=>t.title.toLowerCase().includes(input.value.toLowerCase())).map(t=>'<button class="topic" data-topic="'+t.id+'">'+escape(t.title)+'</button>').join('')||'<p class="muted" style="margin-top:20px">No matching conversations.</p>'; }; input.addEventListener('input',update); update(); input.focus(); } else $('#close-drawer').focus();
}
function closeDrawer() { $('#drawer').hidden=true; if(drawerTrigger?.isConnected) drawerTrigger.focus(); }
function switchTopic(id) { drafts.set(current,$('#message').value); current=id; if(scenario==='first') scenario=$('#scenario').value='returning'; render(); }
document.addEventListener('click',(event)=>{
  const el=event.target.closest('button,a'); if(!el) return;
  if(el.dataset.topic) { event.preventDefault(); closeDrawer(); switchTopic(el.dataset.topic); }
  if(el.dataset.drawer) openDrawer(el.dataset.drawer,el);
  if(el.hasAttribute('data-review')) $('#review').showModal();
  if(el.hasAttribute('data-keep')) notify('Example draft kept. Nothing was sent.');
  if(el.hasAttribute('data-check')) openDrawer('check',el);
  if(el.hasAttribute('data-close')) closeDrawer();
  if(el.hasAttribute('data-revise')) { closeDrawer(); $('#message').value='Revise the venue comparison to focus on the two quietest options.'; $('#message').dispatchEvent(new Event('input')); $('#message').focus(); }
  if(el.hasAttribute('data-save-memory')) { memoryBudget=$('#memory-budget').value; notify('Correction saved for this example only.'); }
  if(el.hasAttribute('data-forget')) { memoryForgotten=true; el.closest('section').remove(); notify('Example preference removed. The conversation is unchanged.'); }
  if(el.hasAttribute('data-pause')) { checkPaused=true; el.textContent='Example check paused'; el.disabled=true; notify('Prototype state changed. No real check was running.'); }
});
$('#close-drawer').onclick=closeDrawer;
document.addEventListener('keydown',(event)=>{ if(event.key==='Escape'&&!$('#drawer').hidden&&!$('#review').open) closeDrawer(); });
$('#theme').onclick=()=>{ document.body.classList.toggle('dark'); $('#theme').setAttribute('aria-label',document.body.classList.contains('dark')?'Switch to light appearance':'Switch to dark appearance'); };
$('#scenario').onchange=(event)=>{ drafts.set(current,$('#message').value); scenario=event.target.value; current='offsite'; queued=''; sent=false; extras.clear(); closeDrawer(); render(); };
$('#new-topic').onclick=()=>switchTopic('new');
$('#message').oninput=()=>{ drafts.set(current,$('#message').value); $('#draft-status').textContent=$('#message').value?'Kept while you explore this prototype':''; };
$('#message').onkeydown=(event)=>{ if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing) { event.preventDefault(); $('#composer').requestSubmit(); } };
$('#composer').onsubmit=(event)=>{ event.preventDefault(); const text=$('#message').value.trim(); if(!text) return; if(scenario==='first') { openDrawer('setup'); return; } if(scenario==='working') { if(queued) { notify('This example supports one queued message. Edit or remove it first.'); return; } queued=text; } else extras.set(current,(extras.get(current)||'')+user(text)+agent('Prototype only: this is where Gator’s real response would appear. No message was sent to a model.')); drafts.delete(current); render(); $('#message').focus(); };
$('#guide').onclick=()=>{ const text=$('#message').value.trim(); if(!text) { $('#message').focus(); return; } extras.set(current,(extras.get(current)||'')+user(text)+agent('Example: your guidance would be routed to the current task. This prototype has no running agent.')); drafts.delete(current); render(); };
$('#edit-queued').onclick=()=>{ if($('#message').value.trim()) { notify('Keep or clear your current draft before editing this message.'); return; } $('#message').value=queued; drafts.set(current,queued); queued=''; renderQueue(); $('#message').focus(); };
$('#remove-queued').onclick=()=>{ queued=''; renderQueue(); notify('Example queued message removed.'); };
$('#confirm-email').onclick=()=>{ sent=true; $('#review').close(); render(); notify('Prototype confirmation only. No email was sent.'); };
render();
